/**
 * Listing galleries are generated by `npm run images` from the raw folders in
 * src/assets/images/Aangan Realty/. `count` must match what the script wrote —
 * `npm test` fails if a listing points at a file that does not exist.
 */
const gallery = (slug: string, count: number) =>
  Array.from(
    { length: count },
    (_, i) =>
      new URL(
        `../assets/properties/${slug}/${String(i + 1).padStart(2, '0')}.webp`,
        import.meta.url,
      ).href,
  )

/** 1 var (sq. yard) = 9 sq.ft. — Gujarat plots and bungalows are quoted in var. */
const VAR = 9

export const PROPERTY_TYPES = [
  'Apartment',
  'Bungalow',
  'Tenement',
  'Studio',
] as const

export const STATUSES = ['For Sale', 'For Rent', 'New Launch'] as const

export type PropertyType = (typeof PROPERTY_TYPES)[number]
export type Status = (typeof STATUSES)[number]

export type Property = {
  id: string
  slug: string
  title: string
  locality: string
  city: string
  /** absolute rupees — kept numeric so filtering and sorting stay honest. 0 = price on request */
  price: number
  /** true when `price` is the entry point of a project, not a single unit */
  priceFrom?: boolean
  /** monthly rupees for rentals, otherwise null */
  rent: number | null
  type: PropertyType
  status: Status
  beds: number
  /** 0 = not stated */
  baths: number
  /** sq.ft. as quoted (carpet, built-up or SBA — the highlights say which). 0 = on request */
  area: number
  facing: string
  furnishing: string
  floor: string
  parking: number
  possession: string
  featured: boolean
  summary: string
  description: string[]
  highlights: string[]
  amenities: string[]
  images: string[]
}

