export const heroImage = new URL('../assets/properties/hero.webp', import.meta.url).href

export const findProperty = (slug: string) =>
  properties.find((p) => p.slug === slug)

/** Two decimals at most, and no trailing zeros — "7.20 Cr" reads wrong. */
const trim = (n: number) =>
  n.toFixed(2).replace(/\.00$/, '').replace(/(\.\d)0$/, '$1')

/** Indian short scale: 47500000 -> "₹4.75 Cr" */
export function formatPrice(rupees: number): string {
  if (rupees >= 10000000) return `₹${trim(rupees / 10000000)} Cr`
  if (rupees >= 100000) return `₹${trim(rupees / 100000)} L`
  return `₹${rupees.toLocaleString('en-IN')}`
}

/** Sale price or monthly rent, whichever this listing actually is. */
export function displayPrice(p: Property): string {
  if (p.rent) return `${formatPrice(p.rent)}/mo`
  if (!p.price) return 'Price on request'
  return `${p.priceFrom ? 'From ' : ''}${formatPrice(p.price)}`
}

/** Rentals have to sort against sale stock somehow — annualise them. */
export function sortValue(p: Property): number {
  return p.rent ? p.rent * 12 : p.price
}

export const cities = [...new Set(properties.map((p) => p.city))].sort()

/** Localities we currently hold stock in — used for the home page ticker. */
export const localities = [...new Set(properties.map((p) => p.locality))]
